// Additional KI2 button inputs generated by the OSD's Extras menu.
// Controls are active high in MiSTer's joystick bit order; the top-level
// merges them with P1/P2 physical inputs before translating to active low.

module ki_extras
(
	input             clk,
	input             reset,
	input             game_ki2,
	input             osd_open,
	input             core_pause,
	input             frame_start,
	input       [1:0] gargos_trigger, // [0] R4/P1, [1] R5/P2
	output     [12:0] controls_p1,
	output     [12:0] controls_p2
);

reg [12:0] gargos_controls;
reg        gargos_player2 = 1'b0;

assign controls_p1 = gargos_player2 ? 13'd0 : gargos_controls;
assign controls_p2 = gargos_player2 ? gargos_controls : 13'd0;

// KI2 arcade Gargos unlock. At character select, select P1 or P2 in the
// OSD: hold Up and tap FP, MP, MK, FK, MP, QP, QK, MK.
//
// Page 2 (Extras) is KI2-only; its R4/R5 actions close the OSD. Latch
// each trigger until the OSD closes and the CPU is running. The shared
// sequencer plays one code at a time and queues the other player's request.
// Every phase lasts three video frames: an Up-only lead-in, alternating
// presses/releases, and a final Up-only release interval.
reg [1:0] gargos_trigger_last = 2'b00;
reg [1:0] gargos_pending      = 2'b00; // [0] P1, [1] P2
reg       gargos_running      = 1'b0;
reg [4:0] gargos_phase        = 5'd0;
reg [1:0] gargos_frame_count  = 2'd0;

wire [1:0] gargos_triggers = gargos_trigger;
wire [1:0] gargos_new_requests = gargos_triggers & ~gargos_trigger_last;
wire [1:0] gargos_requests = gargos_pending | gargos_new_requests;

always @(posedge clk) begin
	gargos_trigger_last <= gargos_triggers;

	if (reset || !game_ki2) begin
		gargos_pending     <= 2'b00;
		gargos_running     <= 1'b0;
		gargos_player2     <= 1'b0;
		gargos_phase       <= 5'd0;
		gargos_frame_count <= 2'd0;
	end
	else begin
		gargos_pending <= gargos_requests;

		if (!gargos_running && !osd_open && !core_pause) begin
			if (gargos_requests[0]) begin
				gargos_pending     <= {gargos_requests[1], 1'b0};
				gargos_player2     <= 1'b0;
				gargos_running     <= 1'b1;
				gargos_phase       <= 5'd0;
				gargos_frame_count <= 2'd0;
			end
			else if (gargos_requests[1]) begin
				gargos_pending     <= 2'b00;
				gargos_player2     <= 1'b1;
				gargos_running     <= 1'b1;
				gargos_phase       <= 5'd0;
				gargos_frame_count <= 2'd0;
			end
		end
		else if (gargos_running && frame_start && !osd_open && !core_pause) begin
			if (gargos_frame_count == 2'd2) begin
				gargos_frame_count <= 2'd0;
				if (gargos_phase == 5'd16) begin
					gargos_phase   <= 5'd0;
					gargos_running <= 1'b0;
				end
				else
					gargos_phase <= gargos_phase + 1'b1;
			end
			else
				gargos_frame_count <= gargos_frame_count + 1'b1;
		end
	end
end

always @(*) begin
	gargos_controls = 13'd0;
	if (gargos_running) begin
		gargos_controls[3] = 1'b1; // Hold Up for the entire sequence.
		case (gargos_phase)
			5'd1:  gargos_controls[6] = 1'b1; // FP: High Fierce
			5'd3:  gargos_controls[5] = 1'b1; // MP: High Medium
			5'd5:  gargos_controls[8] = 1'b1; // MK: Low Medium
			5'd7:  gargos_controls[9] = 1'b1; // FK: Low Fierce
			5'd9:  gargos_controls[5] = 1'b1; // MP: High Medium
			5'd11: gargos_controls[4] = 1'b1; // QP: High Quick
			5'd13: gargos_controls[7] = 1'b1; // QK: Low Quick
			5'd15: gargos_controls[8] = 1'b1; // MK: Low Medium
			default: ; // Lead-in/release phases: Up only.
		endcase
	end
end

endmodule
